                    {/* Content still right-aligned to keep buttons tidy */}
                    <td className="px-6 py-4 rounded-r-2xl border-b border-slate-50 dark:border-slate-700/50 pr-8 text-right">
                      <div className="flex justify-end items-center gap-2">
